const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage', '--font-render-hinting=none']
  });

  const page = await browser.newPage();

  await page.setViewport({ width: 840, height: 1200, deviceScaleFactor: 2 });

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle0', timeout: 30000 });

  await page.waitForTimeout(1500);

  const posterElement = await page.$('.poster');
  const boundingBox = await posterElement.boundingBox();

  await page.setViewport({
    width: 840,
    height: Math.ceil(boundingBox.height),
    deviceScaleFactor: 2
  });

  await page.waitForTimeout(500);

  await posterElement.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png',
    omitBackground: false
  });

  console.log(`Screenshot saved. Dimensions: ${840}x${Math.ceil(boundingBox.height)} @2x`);
  await browser.close();
})();

